// core/theme.js
// Farben je Modus und Fach: Graustufen, eine Akzentfarbe je Prüfungsbereich (Farbcode), Kategorie-Palette, Gold und Feuer für Fortschritt.
(function () {
  const C = {
    light: {
      bg: '#f6f6f8', surface: '#ffffff', surface2: '#f0f0f3', border: '#e2e2e8', text: '#17171c',
      text2: '#52525e', text3: '#9a9aa6', accent: '#4f46e5', accentSoft: '#ecebff', onAccent: '#ffffff',
      ok: '#15803d', okSoft: '#dcf5e4', bad: '#c62828', badSoft: '#fde4e4', line: '#6b6b78', hover: '#ebebf0',
      hl: '#ffec99', hlHot: '#ff9f1a', onHl: '#17171c',
      gold: '#c98a00', goldSoft: '#fff3d1', fire: '#e8590c', fireSoft: '#ffe8d9',
    },
    dark: {
      bg: '#0c0c10', surface: '#15151b', surface2: '#1d1d25', border: '#2b2b35', text: '#f1f1f4',
      text2: '#a9a9b6', text3: '#6c6c7a', accent: '#8b85ff', accentSoft: '#25234a', onAccent: '#0c0c10',
      ok: '#4ade80', okSoft: '#12301f', bad: '#ff7b7b', badSoft: '#3a1618', line: '#8e8e9c', hover: '#23232d',
      hl: '#5a4a12', hlHot: '#ffb938', onHl: '#0c0c10',
      gold: '#ffc53d', goldSoft: '#3a2e0c', fire: '#ff8a4c', fireSoft: '#3d2012',
    },
  };
  // Farbcode der Prüfungsbereiche [hell, dunkel]: Auf jeder Seite übernimmt die Oberfläche die Farbe ihres Fachs.
  const BLOCK = {
    ps: ['#4f46e5', '#8b85ff'], infra: ['#0d9488', '#2dd4bf'], eua: ['#ea580c', '#fb923c'], wiso: ['#16a34a', '#4ade80'],
    de: ['#db2777', '#f472b6'], exam: ['#dc2626', '#f87171'], course: ['#2563eb', '#60a5fa'], ref: ['#7c3aed', '#c4b5fd'],
  };
  // Kategorie-Palette für farbige Begriffe, Karten und Schritte (unabhängig vom Fach).
  const CAT = [['#4f46e5', '#8b85ff'], ['#0d9488', '#2dd4bf'], ['#ea580c', '#fb923c'], ['#16a34a', '#4ade80'], ['#db2777', '#f472b6'], ['#2563eb', '#60a5fa'], ['#ca8a04', '#facc15']];
  const mix = (a, b, t) => {
    const p = (hex) => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
    const x = p(a);
    const y = p(b);
    return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * t).toString(16).padStart(2, '0')).join('');
  };
  const dark = (mode) => mode === 'dark';
  const softOf = (mode, col) => mix(C[mode].surface, col, dark(mode) ? 0.2 : 0.11);
  let tone = 'ps';
  const cache = {};
  const build = (mode, t) => {
    const base = C[mode];
    const i = dark(mode) ? 1 : 0;
    const acc = (BLOCK[t] || BLOCK.ps)[i];
    const out = Object.assign({}, base, {accent: acc, accentSoft: softOf(mode, acc), onAccent: dark(mode) ? '#0c0c10' : '#ffffff'});
    out.cat = CAT.map((pair) => pair[i]);
    out.catSoft = CAT.map((pair) => softOf(mode, pair[i]));
    CAT.forEach((pair, k) => { out['cat' + k] = pair[i]; out['catSoft' + k] = softOf(mode, pair[i]); });
    out.block = {};
    out.blockSoft = {};
    Object.keys(BLOCK).forEach((k) => { out.block[k] = BLOCK[k][i]; out.blockSoft[k] = softOf(mode, BLOCK[k][i]); });
    return out;
  };
  const bound = new Map();
  const c = () => {
    const key = AP2.state.get('theme') + ':' + tone;
    return cache[key] || (cache[key] = build(AP2.state.get('theme'), tone));
  };
  const bind = (el, fn) => { bound.set(el, fn); fn(el, c()); return el; };
  const unbind = (el) => { bound.delete(el); };
  const apply = () => bound.forEach((fn, el) => fn(el, c()));
  const toggle = () => AP2.state.set('theme', AP2.state.get('theme') === 'light' ? 'dark' : 'light');
  // Fachfarbe wechseln (vor dem Aufbau einer Ansicht), bestehende Elemente werden umgefärbt.
  const setTone = (t) => {
    const next = BLOCK[t] ? t : 'ps';
    if (next === tone) return;
    tone = next;
    apply();
    const meta = document.querySelector('meta[name="theme-color"]');
    if (meta) meta.setAttribute('content', c().accent);
  };
  AP2.state.sub('theme', apply);
  AP2.theme = {C, BLOCK, c, bind, unbind, apply, toggle, setTone, tone: () => tone, mix};
})();
;
// core/dom.js
// DOM-Helfer: Elemente erzeugen, Stile setzen, Listener verfolgen und sauber entfernen.
(function () {
  const listeners = new WeakMap();
  const st = (el, obj) => Object.assign(el.style, obj);
  const on = (el, type, fn) => {
    el.addEventListener(type, fn);
    if (!listeners.has(el)) listeners.set(el, []);
    listeners.get(el).push([type, fn]);
    return el;
  };
  const kid = (el, kids) => {
    [].concat(kids).flat(Infinity).forEach((item) => {
      if (item == null || item === false) return;
      el.appendChild(item instanceof Node ? item : document.createTextNode(String(item)));
    });
  };
  const h = (tag, cfg, kids) => {
    const el = document.createElement(tag);
    const o = cfg || {};
    if (o.text != null) el.textContent = o.text;
    if (o.attrs) Object.keys(o.attrs).forEach((key) => el.setAttribute(key, o.attrs[key]));
    if (o.style) st(el, o.style);
    if (o.on) Object.keys(o.on).forEach((key) => on(el, key, o.on[key]));
    kid(el, kids || []);
    return el;
  };
  const svg = (tag, attrs, kids) => {
    const el = document.createElementNS('http://www.w3.org/2000/svg', tag);
    Object.keys(attrs || {}).forEach((key) => el.setAttribute(key, attrs[key]));
    kid(el, kids || []);
    return el;
  };
  const inline = (kind, text) => {
    // Fettgedruckte Schlüsselbegriffe erscheinen in der Fachfarbe: beim Überfliegen springen sie ins Auge.
    if (kind === 'b') return AP2.theme.bind(h('strong', {text, style: {fontWeight: AP2.S.fw.semi}}), (e, col) => { e.style.color = col.accent; });
    const el = h('code', {text, style: {fontFamily: AP2.S.font.mono, fontSize: '0.88em', padding: '1px 6px',
      borderRadius: AP2.S.r.sm, border: '1px solid'}});
    return AP2.theme.bind(el, (e, col) => st(e, {backgroundColor: col.surface2, borderColor: col.border}));
  };
  const rich = (str) => {
    const frag = document.createDocumentFragment();
    String(str).split(/(\*\*[^*]+\*\*|`[^`]+`)/).forEach((part) => {
      if (!part) return;
      if (part.startsWith('**')) frag.appendChild(inline('b', part.slice(2, -2)));
      else if (part.startsWith('`')) frag.appendChild(inline('c', part.slice(1, -1)));
      else frag.appendChild(document.createTextNode(part));
    });
    return frag;
  };
  // Wie rich, aber fette Stellen werden zu farbigen Markern: tone 'cat' wechselt die Farbe je Begriff (Merkhilfen), sonst Fachfarbe.
  const marked = (str, tone) => {
    const frag = document.createDocumentFragment();
    let n = 0;
    String(str).split(/(\*\*[^*]+\*\*|`[^`]+`)/).forEach((part) => {
      if (!part) return;
      if (part.startsWith('**')) {
        const i = n++;
        const el = h('span', {text: part.slice(2, -2), style: {fontWeight: AP2.S.fw.semi, padding: '0 5px', borderRadius: '5px', boxDecorationBreak: 'clone', webkitBoxDecorationBreak: 'clone'}});
        AP2.theme.bind(el, (e, col) => {
          const k = i % col.cat.length;
          st(e, tone === 'cat' ? {backgroundColor: col.catSoft[k], color: col.cat[k]} : {backgroundColor: col.accentSoft, color: col.text});
        });
        frag.appendChild(el);
      } else if (part.startsWith('`')) frag.appendChild(inline('c', part.slice(1, -1)));
      else frag.appendChild(document.createTextNode(part));
    });
    return frag;
  };
  const release = (el) => {
    (listeners.get(el) || []).forEach(([type, fn]) => el.removeEventListener(type, fn));
    listeners.delete(el);
    AP2.theme.unbind(el);
  };
  const dispose = (root) => {
    root.querySelectorAll('*').forEach(release);
    while (root.firstChild) root.removeChild(root.firstChild);
  };
  Object.assign(AP2, {h, st, on, svg, rich, marked, dispose});
})();
;
// core/layout.js
// Responsive Berechnung aller Breiten bei jedem Resize (kein max-width/min-width).
(function () {
  const S = AP2.S;
  const L = {w: 0, h: 0, mobile: false, sidebarW: 0, mainW: 0, contentW: 0, pad: 0, subs: []};
  const compute = () => {
    L.w = document.documentElement.clientWidth || window.innerWidth;
    L.h = window.innerHeight;
    L.mobile = L.w < S.bp.mobile;
    const want = AP2.state.get('sideW') || S.w.sidebar;
    L.sidebarW = L.mobile ? Math.min(S.w.sidebar, L.w - 56) : Math.max(S.w.sideMin, Math.min(S.w.sideMax, L.w * 0.6, want));
    L.mainW = L.mobile ? L.w : L.w - L.sidebarW;
    L.pad = L.mobile ? S.w.padMobile : S.w.pad;
    L.contentW = Math.min(S.w.content, L.mainW - L.pad * 2);
  };
  const run = () => { compute(); L.subs.forEach((fn) => fn(L)); };
  const bind = (fn) => {
    L.subs.push(fn);
    fn(L);
    return () => { L.subs = L.subs.filter((item) => item !== fn); };
  };
  window.addEventListener('resize', run);
  // Erscheint oder verschwindet die senkrechte Bildlaufleiste, ändert sich die nutzbare Breite ohne resize-Ereignis.
  if (window.ResizeObserver) new ResizeObserver(() => { if ((document.documentElement.clientWidth || window.innerWidth) !== L.w) run(); }).observe(document.documentElement);
  AP2.state.sub('sideW', run);
  compute();
  AP2.layout = Object.assign(L, {bind, run});
})();
;
// core/router.js
// Hash-Router: #/seiten-id
(function () {
  const current = () => decodeURIComponent(location.hash.replace(/^#\/?/, '')) || 'home';
  const go = (id) => { location.hash = '/' + id; };
  window.addEventListener('hashchange', () => AP2.state.set('route', current()));
  AP2.router = {current, go};
})();
;
// core/store.js
// Inhaltsspeicher: Seiten registrieren und in Teilen erweitern (Suche: core/index.js, core/search.js).
(function () {
  const BLOCKS = [
    {id: 'ps', icon: 'clipboard', short: 'Planen', t: 'Planen eines Softwareproduktes', s: 'Projektmanagement, Anforderungen, UML, Datenmodellierung, Qualität, Recht'},
    {id: 'infra', icon: 'network', short: 'Infrastruktur', t: 'Infrastruktur und IT-Sicherheit', s: 'Netzwerke, Storage, Verfügbarkeit, Kryptografie, Angriffe'},
    {id: 'eua', icon: 'code', short: 'Algorithmen', t: 'Entwicklung und Algorithmen', s: 'Programmierung, OOP, Datenstrukturen, Algorithmen, Muster, SQL'},
    {id: 'wiso', icon: 'briefcase', short: 'WiSo', t: 'Wirtschafts- und Sozialkunde', s: 'Ausbildung, Arbeitsrecht, Mitbestimmung, Sozialversicherung, Wirtschaft'},
    {id: 'de', icon: 'pen', short: 'Deutsch', t: 'Deutsch', s: 'Textformen, Kommunikation, Präsentation, Sprachrichtigkeit'},
    {id: 'exam', icon: 'trophy', short: 'Prüfungen', t: 'Probeprüfungen', s: 'Realistische Prüfungen mit Zeitlimit, Selbstbewertung und Note'},
    {id: 'course', icon: 'book', short: 'Kurse', t: 'Programmierkurse', s: 'Python, Java, C#, SQL, HTML und CSS in 56 ausführlichen Kapiteln'},
    {id: 'ref', icon: 'bookmark', short: 'Nachschlagen', t: 'Nachschlagen', s: 'Prüfungsablauf, Projektarbeit, Glossar, Formeln, Strategie'},
  ];
  const pages = new Map();
  const page = (id, cfg) => { pages.set(id, Object.assign({id, blocks: []}, cfg)); };
  const add = (id, blocks) => {
    const target = pages.get(id);
    if (target) target.blocks.push(...blocks); else console.error('Seite fehlt: ' + id);
  };
  const addTop = (id, blocks) => {
    const target = pages.get(id);
    if (target) target.blocks.unshift(...blocks); else console.error('Seite fehlt: ' + id);
  };
  const get = (id) => pages.get(id);
  const block = (id) => BLOCKS.find((b) => b.id === id);
  const byBlock = (blockId) => [...pages.values()].filter((p) => p.b === blockId);
  const all = () => [].concat(...BLOCKS.map((blk) => byBlock(blk.id)));
  const neighbors = (id) => {
    const list = all();
    const idx = list.findIndex((p) => p.id === id);
    return {prev: list[idx - 1], next: list[idx + 1]};
  };
  AP2.store = {BLOCKS, page, add, get, block, byBlock, all, neighbors};
  AP2.page = page;
  AP2.add = add;
  AP2.addTop = addTop;
})();
;
// core/index.js
// Suchindex: zerlegt jede Seite in Textabschnitte (Art, Überschrift, Text) für die Volltextsuche.
(function () {
  const LABEL = {h: 'Abschnitt', def: 'Prüfungsdefinition', merk: 'Merkhilfe', cheat: 'Spickzettel', tip: 'Prüfungstipp', warn: 'Prüfungsfalle',
    note: 'Hinweis', ex: 'Beispiel', code: 'Code', table: 'Tabelle', qa: 'Aufgabe', sol: 'Musterlösung', quiz: 'Selbsttest', fig: 'Abbildung'};
  const WEIGHT = {h: 5, def: 3, merk: 2.5, cheat: 2, tip: 1.5, warn: 1.5, text: 1.5, table: 1.2, qa: 1.2, quiz: 0.7};
  // Kleinschreibung ohne Umlautpunkte und Akzente; die Länge bleibt gleich, damit Fundstellen auf den Originaltext passen.
  const fold = (str) => {
    const low = str.toLowerCase();
    const bare = low.normalize('NFD').replace(/[̀-ͯ]/g, '');
    if (bare.length === str.length) return bare;
    return low.length === str.length ? low : str;
  };
  // Nur Buchstaben und Ziffern: so lässt sich ein Abschnitt unabhängig von Auszeichnung und Leerraum im DOM wiederfinden.
  const sk = (str) => str.toLowerCase().normalize('NFD').replace(/[^\p{L}\p{N}]+/gu, '');
  const plain = (str) => str.replace(/\*\*([^*]+)\*\*|`([^`]+)`/g, (all, bold, code) => bold || code);
  const CALLOUTS = ['def', 'merk', 'tip', 'warn', 'note', 'ex'];
  const build = (p) => {
    const segs = [];
    let head = '';
    let force = '';
    const emit = (kind, raw, isCode) => {
      if (typeof raw !== 'string' && typeof raw !== 'number') return;
      const text = isCode ? String(raw).replace(/^\n+|\s+$/g, '') : plain(String(raw));
      if (text.trim()) segs.push({kind: force || kind, text, fold: fold(text), head});
    };
    const each = (kind, val) => [].concat(val == null ? [] : val).forEach((item) => emit(kind, item));
    const title = (txt) => { head = ''; emit('h', txt); head = plain(String(txt)); };
    const inSol = (fn) => { force = 'sol'; fn(); force = ''; };
    const answer = (val) => inSol(() => [].concat(val == null ? [] : val).forEach((item) => (Array.isArray(item) ? block(item)
      : emit('text', String(item).replace(/^- /, '')))));
    const T = {
      p: (txt) => emit('text', txt),
      h: title,
      h3: title,
      list: (items) => items.forEach((item) => (Array.isArray(item) ? (emit('text', item[0]), each('text', item[1])) : emit('text', item))),
      steps: (items) => each('text', items),
      kv: (pairs) => pairs.forEach((pair) => emit('text', pair[0] + ': ' + pair[1])),
      cheat: (cards) => cards.forEach((card) => { emit('cheat', card[0]); each('cheat', card[1]); }),
      code: (lang, src) => emit('code', src, true),
      codes: (list) => list.forEach((item) => emit('code', item[1], true)),
      qa: (question, ans) => { emit('qa', question); answer(ans); },
      quiz: (questions) => questions.forEach((q) => { emit('quiz', q.q); each('quiz', q.o); emit('quiz', q.e); }),
      table: (cols, rows) => { emit('table', cols.join(' | ')); rows.forEach((row) => emit('table', row.join(' | '))); },
      procon: (name, pros, cons) => { emit('text', name); each('text', pros); each('text', cons); },
      row: (blocks) => blocks.forEach(block),
      exam: (cfg) => {
        emit('note', cfg.hint);
        cfg.parts.forEach((part) => {
          title(part.t);
          emit('text', part.intro);
          part.tasks.forEach((task) => {
            (task.ctx || []).forEach(block);
            emit('qa', task.q);
            answer(task.a);
            inSol(() => (task.sol || []).forEach(block));
          });
        });
      },
      see: () => {},
      signs: (items, cap) => { items.forEach((it) => { emit('fig', it[2]); emit('fig', it[3]); }); emit('fig', cap); },
      tool: () => {},
    };
    CALLOUTS.forEach((kind) => { T[kind] = (body) => each(kind, body); });
    // Unbekannte Blöcke (Diagramme): nur die Bildunterschrift ist als Text auffindbar.
    const caption = (args) => args.forEach((arg) => { if (arg && typeof arg === 'object' && !Array.isArray(arg)) emit('fig', arg.cap); });
    function block(item) {
      if (!Array.isArray(item)) return;
      const fn = T[item[0]];
      if (fn) fn.apply(null, item.slice(1)); else caption(item.slice(1));
    }
    each('def', p.d);
    each('merk', p.m);
    if (p.cheat) T.cheat(p.cheat);
    p.blocks.forEach(block);
    return {page: p, segs, title: fold(p.t), group: fold(p.g || ''), hay: segs.map((seg) => seg.fold).join('\n')};
  };
  let cache = null;
  const all = () => {
    if (!cache) cache = AP2.store.all().map(build);
    return cache;
  };
  const get = (id) => all().find((ix) => ix.page.id === id);
  // Position jedes Abschnitts im Buchstabengerüst der Seite (erst beim Springen nötig).
  const skeleton = (ix) => {
    if (ix.sk == null) {
      let at = 0;
      ix.sk = ix.segs.map((seg) => { seg.sk = sk(seg.text); seg.at = at; at += seg.sk.length; return seg.sk; }).join('');
    }
    return ix.sk;
  };
  AP2.index = {LABEL, WEIGHT, fold, sk, plain, all, get, skeleton};
})();
;
// core/search.js
// Volltextsuche: Abfrage zerlegen, Seiten und Fundstellen gewichten, Tippfehler ausgleichen.
(function () {
  const {fold, WEIGHT} = AP2.index;
  const ALNUM = /[\p{L}\p{N}]/u;
  // Wörter sind UND-verknüpft, "in Anführungszeichen" steht für eine genaue Wortfolge.
  const parse = (query) => {
    const terms = [];
    fold(query).replace(/"([^"]+)"|(\S+)/g, (all, phrase, word) => {
      const term = (phrase || word).replace(/"/g, '').trim();
      if (term && !terms.includes(term)) terms.push(term);
      return '';
    });
    return terms;
  };
  const atWord = (hay, i) => i === 0 || !ALNUM.test(hay[i - 1]);
  // Alle Fundstellen der Begriffe als sortierte, zusammengefasste Bereiche [von, bis].
  const ranges = (hay, terms) => {
    const list = [];
    terms.forEach((term) => {
      for (let i = hay.indexOf(term); i >= 0; i = hay.indexOf(term, i + term.length)) list.push([i, i + term.length]);
    });
    list.sort((x, y) => x[0] - y[0] || y[1] - x[1]);
    const out = [];
    list.forEach((r) => {
      const last = out[out.length - 1];
      if (last && r[0] < last[1]) last[1] = Math.max(last[1], r[1]); else out.push(r);
    });
    return out;
  };
  const segHit = (seg, terms, phrase) => {
    let sum = 0;
    let n = 0;
    let a = -1;
    let len = 0;
    terms.forEach((term) => {
      const i = seg.fold.indexOf(term);
      if (i < 0) return;
      n++;
      sum += atWord(seg.fold, i) ? 1.4 : 1;
      if (a < 0 || i < a) { a = i; len = term.length; }
    });
    if (!n) return null;
    // Kurze Abschnitte, mehrere Begriffe im selben Abschnitt und ein Treffer ganz am Anfang (Glossarbegriff) zählen mehr.
    let score = sum * (WEIGHT[seg.kind] || 1) * (1 + 0.6 * (n - 1)) * (1 + 30 / (30 + seg.text.length)) * (a === 0 ? 1.5 : 1);
    const at = phrase ? seg.fold.indexOf(phrase) : -1;
    if (at >= 0) { score *= 2; a = at; len = phrase.length; }
    return {score, a, b: a + len};
  };
  const titleScore = (ix, terms, phrase) => {
    let sum = 0;
    terms.forEach((term) => {
      const i = ix.title.indexOf(term);
      if (ix.title === term) sum += 120;
      else if (i === 0) sum += 70;
      else if (i > 0) sum += atWord(ix.title, i) ? 50 : 30;
      else if (ix.group.includes(term)) sum += 12;
    });
    if (phrase && ix.title.includes(phrase)) sum += ix.title === phrase ? 160 : 60;
    return sum;
  };
  const scan = (ix, terms, phrase, needAll) => {
    const inPage = (term) => ix.title.includes(term) || ix.group.includes(term) || ix.hay.includes(term);
    if (needAll ? !terms.every(inPage) : !terms.some(inPage)) return null;
    const hits = [];
    ix.segs.forEach((seg, si) => {
      const hit = segHit(seg, terms, phrase);
      if (hit) { hit.si = si; hits.push(hit); }
    });
    hits.sort((x, y) => y.score - x.score || x.si - y.si);
    const top = hits.slice(0, 3);
    const head = titleScore(ix, terms, phrase);
    const body = top.reduce((sum, hit, idx) => sum + hit.score / (1 << idx), 0) + Math.log2(1 + hits.length);
    return {ix, score: head + body, inTitle: terms.some((term) => ix.title.includes(term)), hits: top, total: hits.length};
  };
  const rank = (terms, needAll) => {
    const phrase = terms.length > 1 ? terms.join(' ') : '';
    return AP2.index.all().map((ix) => scan(ix, terms, phrase, needAll)).filter(Boolean).sort((x, y) => y.score - x.score);
  };
  // Editierabstand (mit Buchstabendrehern), bricht ab, sobald max überschritten ist.
  const dist = (a, b, max) => {
    if (Math.abs(a.length - b.length) > max) return max + 1;
    let prev2 = [];
    let prev = Array.from({length: b.length + 1}, (_, j) => j);
    for (let i = 1; i <= a.length; i++) {
      const cur = [i];
      let low = i;
      for (let j = 1; j <= b.length; j++) {
        cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
        if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) cur[j] = Math.min(cur[j], prev2[j - 2] + 1);
        if (cur[j] < low) low = cur[j];
      }
      if (low > max) return max + 1;
      prev2 = prev;
      prev = cur;
    }
    return prev[b.length];
  };
  let vocab = null;
  const words = () => {
    if (vocab) return vocab;
    vocab = new Map();
    const take = (text) => (text.match(/[\p{L}\p{N}]{4,}/gu) || []).forEach((word) => {
      const key = fold(word);
      const rec = vocab.get(key);
      if (rec) rec[0]++; else vocab.set(key, [1, word]);
    });
    AP2.index.all().forEach((ix) => { take(ix.page.t); ix.segs.forEach((seg) => take(seg.text)); });
    return vocab;
  };
  // Ähnlichstes bekanntes Wort (oder Wortanfang, solange noch getippt wird) für einen Begriff ohne Treffer.
  const suggest = (term) => {
    if (term.length < 4 || /\s/.test(term)) return null;
    const max = term.length < 7 ? 1 : 2;
    let best = null;
    let bestD = max + 1;
    let bestN = 0;
    words().forEach((rec, key) => {
      if (key[0] !== term[0]) return;
      const cuts = key.length <= term.length + max ? [key.length] : [term.length, term.length + 1];
      cuts.forEach((cut) => {
        const d = dist(term, key.slice(0, cut), max);
        if (d < bestD || (d === bestD && d <= max && rec[0] > bestN)) { best = [key.slice(0, cut), rec[1].slice(0, cut)]; bestD = d; bestN = rec[0]; }
      });
    });
    return best;
  };
  const known = (term) => AP2.index.all().some((ix) => ix.title.includes(term) || ix.hay.includes(term));
  const run = (query) => {
    let terms = parse(query);
    const shown = query.trim().replace(/\s+/g, ' ');
    if (terms.join('').length < 2) return {terms: [], results: [], shown, fixed: ''};
    let results = rank(terms, true);
    let fixed = '';
    if (!results.length) {
      const fixes = terms.map((term) => (known(term) ? null : suggest(term)));
      const better = terms.map((term, idx) => (fixes[idx] ? fixes[idx][0] : term));
      const again = fixes.some(Boolean) ? rank(better, true) : [];
      if (again.length) {
        results = again;
        fixed = terms.map((term, idx) => (fixes[idx] ? fixes[idx][1] : term)).join(' ');
        terms = better;
      }
    }
    if (!results.length && terms.length > 1) results = rank(terms, false);
    return {terms, results, shown: fixed || shown, fixed};
  };
  // Alle Fundstellen einer Seite in Lesereihenfolge: {si: Abschnitt, a: von, b: bis}.
  const marks = (id, terms) => {
    const ix = AP2.index.get(id);
    const out = [];
    if (ix) ix.segs.forEach((seg, si) => ranges(seg.fold, terms).forEach((r) => out.push({si, a: r[0], b: r[1]})));
    return out;
  };
  AP2.search = {run, ranges, marks};
})();
