// ui/press.js
// Interaktive Elemente: Hover, Fokus, Tastatur (Enter/Leertaste) und Theme in einem Helfer.
(function () {
  const {h, st, on} = AP2;
  const S = AP2.S;
  let keyboardMode = false;
  document.addEventListener('keydown', (ev) => { if (ev.key === 'Tab') keyboardMode = true; });
  document.addEventListener('pointerdown', () => { keyboardMode = false; });
  const press = (el, cfg) => {
    let hovered = false;
    let focused = false;
    el.tabIndex = 0;
    el.setAttribute('role', cfg.role || 'button');
    if (cfg.label) el.setAttribute('aria-label', cfg.label);
    st(el, {cursor: 'pointer', outline: 'none', userSelect: 'none', webkitTapHighlightColor: 'transparent', transition: S.t.fast});
    const paint = () => {
      const col = AP2.theme.c();
      el.style.boxShadow = 'none';
      st(el, cfg.base(col));
      if (hovered && cfg.hover) st(el, cfg.hover(col));
      if (focused && keyboardMode) el.style.boxShadow = '0 0 0 ' + S.ring + 'px ' + col.accent;
    };
    AP2.theme.bind(el, paint);
    on(el, 'pointerenter', () => { hovered = true; paint(); });
    on(el, 'pointerleave', () => { hovered = false; paint(); });
    on(el, 'pointercancel', () => { hovered = false; paint(); });
    on(el, 'focus', () => { focused = true; paint(); });
    on(el, 'blur', () => { focused = false; paint(); });
    on(el, 'click', (ev) => cfg.fn(ev));
    on(el, 'keydown', (ev) => {
      if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); cfg.fn(ev); }
    });
    el.repaint = paint;
    return el;
  };
  const LOOK = {
    primary: (c) => ({backgroundColor: c.accent, color: c.onAccent, borderColor: c.accent, opacity: '1'}),
    soft: (c) => ({backgroundColor: c.surface2, color: c.text, borderColor: c.border, opacity: '1'}),
    ghost: (c) => ({backgroundColor: 'transparent', color: c.text2, borderColor: 'transparent', opacity: '1'}),
  };
  const HOVER = {
    primary: () => ({opacity: '0.88'}),
    soft: (c) => ({backgroundColor: c.hover}),
    ghost: (c) => ({backgroundColor: c.hover, color: c.text}),
  };
  const btn = (cfg) => {
    const kind = cfg.kind || 'soft';
    const small = cfg.small;
    const el = h('div', {style: {display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: S.sp[2],
      padding: small ? '6px 12px' : '10px 18px', borderRadius: S.r.md, border: '1px solid',
      fontSize: small ? S.f.sm : S.f.md, fontWeight: S.fw.med, lineHeight: S.lh.tight}}, [cfg.icon, cfg.text]);
    return press(el, {fn: cfg.fn, label: cfg.label, base: LOOK[kind], hover: HOVER[kind]});
  };
  const field = (el) => {
    let focused = false;
    const paint = (node, col) => st(node, {backgroundColor: col.surface, color: col.text, fontFamily: S.font.sans,
      border: '1px solid ' + (focused ? col.accent : col.border), borderRadius: S.r.md, padding: '10px 12px',
      fontSize: S.f.md, outline: 'none', boxSizing: 'border-box'});
    AP2.theme.bind(el, paint);
    on(el, 'pointercancel', () => { hovered = false; paint(); });
    on(el, 'focus', () => { focused = true; paint(el, AP2.theme.c()); });
    on(el, 'blur', () => { focused = false; paint(el, AP2.theme.c()); });
    return el;
  };
  Object.assign(AP2, {press, btn, field});
})();
;
// ui/text.js
// Textblöcke: Absatz, Überschriften, Listen, Schritte, Begriffstabelle.
(function () {
  const {h, rich} = AP2;
  const S = AP2.S;
  const B = AP2.blocks;
  const tint = (el, key) => AP2.theme.bind(el, (n, c) => { n.style.color = c[key]; });
  const fill = (el, key) => AP2.theme.bind(el, (n, c) => { n.style.backgroundColor = c[key]; });
  Object.assign(AP2, {tint, fill});
  B.p = (txt) => tint(h('p', {style: {margin: '0 0 ' + S.sp[4], fontSize: S.f.md, lineHeight: S.lh.body}}, rich(txt)), 'text');
  B.h = (txt) => {
    const bar = fill(h('span', {style: {width: '4px', height: '24px', borderRadius: S.r.pill, flexShrink: 0}}), 'accent');
    const title = tint(h('h2', {text: txt, style: {margin: 0, fontSize: S.f.h2, fontWeight: S.fw.bold,
      lineHeight: S.lh.tight, letterSpacing: '-0.01em'}}), 'text');
    return h('div', {style: {display: 'flex', alignItems: 'center', gap: S.sp[3], margin: S.sp[7] + ' 0 ' + S.sp[4]}}, [bar, title]);
  };
  B.h3 = (txt) => tint(h('h3', {text: txt, style: {fontSize: S.f.xl, fontWeight: S.fw.semi, lineHeight: S.lh.tight,
    margin: S.sp[5] + ' 0 ' + S.sp[2]}}), 'text');
  const listRow = (item, sub) => {
    const size = sub ? '5px' : '7px';
    const dot = h('span', {style: {width: size, height: size, borderRadius: '50%', marginTop: sub ? '12px' : '11px', flexShrink: 0}});
    AP2.theme.bind(dot, (n, c) => { n.style.backgroundColor = sub ? c.text3 : c.accent; });
    const body = tint(h('div', {style: {flex: '1 1 0', fontSize: sub ? S.f.sm : S.f.md, lineHeight: S.lh.body,
      overflowWrap: 'break-word'}}, rich(item)), sub ? 'text2' : 'text');
    return h('div', {style: {display: 'flex', gap: S.sp[3], padding: '2px 0', marginLeft: sub ? S.sp[5] : '0'}}, [dot, body]);
  };
  B.list = (items) => {
    const wrap = h('div', {style: {margin: '0 0 ' + S.sp[5]}});
    items.forEach((item) => {
      if (Array.isArray(item)) {
        wrap.appendChild(listRow(item[0], false));
        item[1].forEach((subItem) => wrap.appendChild(listRow(subItem, true)));
      } else wrap.appendChild(listRow(item, false));
    });
    return wrap;
  };
  // Schritte als farbige Zeitleiste: jede Nummer in eigener Farbe, die Linie verläuft zur nächsten Farbe.
  const stepRow = (item, idx, last) => {
    const badge = h('div', {text: String(idx + 1), style: {position: 'absolute', left: 0, top: 0, width: '30px', height: '30px',
      borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: S.f.sm,
      fontWeight: S.fw.bold, boxShadow: '0 2px 6px rgba(0,0,0,0.12)'}});
    AP2.theme.bind(badge, (n, c) => { const k = idx % c.cat.length; n.style.backgroundColor = c.cat[k]; n.style.color = c.surface; });
    const rail = last ? null : AP2.theme.bind(h('div', {style: {position: 'absolute', left: '14px', top: '34px', bottom: '0', width: '3px', borderRadius: '2px'}}),
      (n, c) => { const k = idx % c.cat.length; n.style.background = 'linear-gradient(' + c.cat[k] + ', ' + c.cat[(k + 1) % c.cat.length] + ')'; n.style.opacity = '0.45'; });
    const body = tint(h('div', {style: {fontSize: S.f.md, lineHeight: S.lh.body, paddingTop: '2px'}}, rich(item)), 'text');
    return h('div', {style: {position: 'relative', paddingLeft: '48px', paddingBottom: last ? '0' : S.sp[4]}}, [badge, rail, body]);
  };
  B.steps = (items) => h('div', {style: {margin: '0 0 ' + S.sp[5]}}, items.map((item, idx) => stepRow(item, idx, idx === items.length - 1)));
  B.kv = (pairs) => {
    const box = h('div', {style: {border: '1px solid', borderRadius: S.r.md, overflow: 'hidden', margin: '0 0 ' + S.sp[5]}});
    AP2.theme.bind(box, (n, c) => { n.style.borderColor = c.border; n.style.backgroundColor = c.surface; });
    pairs.forEach((pair, idx) => {
      // Begriff als farbiges Etikett, jede Zeile eine andere Farbe.
      const chip = h('span', {style: {display: 'inline-block', padding: '3px 10px', borderRadius: S.r.sm, fontWeight: S.fw.semi, lineHeight: '1.4'}}, rich(String(pair[0]).replace(/\*\*/g, '')));
      AP2.theme.bind(chip, (n, c) => { const k = idx % c.cat.length; n.style.backgroundColor = c.catSoft[k]; n.style.color = c.cat[k]; });
      const term = h('div', {style: {flex: '0 0 200px', fontSize: S.f.sm}}, [chip]);
      const desc = tint(h('div', {style: {flex: '1 1 260px', fontSize: S.f.sm, lineHeight: S.lh.body}}, rich(pair[1])), 'text');
      const row = h('div', {style: {display: 'flex', flexWrap: 'wrap', gap: S.sp[2] + ' ' + S.sp[4], padding: '12px 16px', borderTop: idx ? '1px solid' : 'none'}}, [term, desc]);
      AP2.theme.bind(row, (n, c) => { n.style.borderColor = c.border; });
      box.appendChild(row);
    });
    return box;
  };
})();
;
// ui/callout.js
// Hervorgehobene Kästen mit Symbol und eigener Farbe: Definition (Fachfarbe), Merkhilfe (Gold, bunte Schlüsselbegriffe), Tipp, Falle, Hinweis, Beispiel.
(function () {
  const {h, rich} = AP2;
  const S = AP2.S;
  const KINDS = {
    def: {label: 'Prüfungsdefinition', icon: 'book', bar: 'accent', bg: 'accentSoft', big: true, mark: 'acc'},
    merk: {label: 'Merkhilfe', icon: 'bulb', bar: 'gold', bg: 'goldSoft', mark: 'cat'},
    tip: {label: 'Prüfungstipp', icon: 'check', bar: 'ok', bg: 'okSoft'},
    warn: {label: 'Prüfungsfalle', icon: 'alert', bar: 'bad', bg: 'badSoft'},
    note: {label: 'Hinweis', icon: 'info', bar: 'text3', bg: 'surface'},
    ex: {label: 'Beispiel', icon: 'flask', bar: 'cat5', bg: 'surface2'},
  };
  const color = (c, key) => (key === 'cat5' ? c.cat[5] : key === 'text3' ? c.text2 : c[key]);
  const callout = (kind, body) => {
    const cfg = KINDS[kind];
    const ic = h('span', {style: {width: '26px', height: '26px', borderRadius: '50%', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0}}, [AP2.icon(cfg.icon, 15)]);
    const label = h('div', {style: {display: 'flex', alignItems: 'center', gap: S.sp[2], fontSize: S.f.xs, fontWeight: S.fw.bold, textTransform: 'uppercase',
      letterSpacing: '0.08em', marginBottom: S.sp[2]}}, [ic, h('span', {text: cfg.label})]);
    AP2.theme.bind(label, (n, c) => { n.style.color = color(c, cfg.bar); ic.style.backgroundColor = color(c, cfg.bar); ic.style.color = c.surface; });
    const box = h('div', {style: {padding: '14px 20px 16px', borderRadius: S.r.md, margin: '0 0 ' + S.sp[5], border: '1px solid',
      borderLeftWidth: '5px'}}, [label]);
    AP2.theme.bind(box, (n, c) => { n.style.backgroundColor = cfg.bg === 'surface2' ? c.surface2 : c[cfg.bg]; n.style.borderColor = c.border; n.style.borderLeftColor = color(c, cfg.bar); });
    [].concat(body).forEach((line, idx, list) => {
      const para = h('div', {style: {fontSize: cfg.big ? S.f.lg : S.f.md, lineHeight: cfg.mark ? '1.9' : S.lh.body,
        marginBottom: idx === list.length - 1 ? '0' : S.sp[2], fontWeight: cfg.big ? S.fw.med : S.fw.reg}}, cfg.mark ? AP2.marked(line, cfg.mark) : rich(line));
      box.appendChild(AP2.tint(para, 'text'));
    });
    return box;
  };
  Object.keys(KINDS).forEach((kind) => { AP2.blocks[kind] = (body) => callout(kind, body); });
})();
;
// ui/table.js
// Tabellen mit Kopfzeile, optional markierten Zeilen und horizontalem Scrollen auf kleinen Geräten.
(function () {
  const {h, rich} = AP2;
  const S = AP2.S;
  const cell = (tag, content, style, paint) => {
    const el = h(tag, {style: Object.assign({padding: '10px 14px', textAlign: 'left', verticalAlign: 'top'}, style)}, rich(content));
    return AP2.theme.bind(el, paint);
  };
  AP2.blocks.table = (head, rows, opts) => {
    const o = opts || {};
    const mark = o.mark || [];
    const table = h('table', {style: {width: '100%', borderCollapse: 'collapse', fontSize: S.f.sm, lineHeight: '1.55'}});
    const headRow = h('tr');
    head.forEach((txt) => headRow.appendChild(cell('th', txt, {fontWeight: S.fw.semi, whiteSpace: 'nowrap'}, (n, c) => {
      n.style.backgroundColor = c.accentSoft; n.style.color = c.accent; n.style.borderBottom = '2px solid ' + c.accent;
    })));
    table.appendChild(h('thead', {}, [headRow]));
    const body = h('tbody');
    rows.forEach((row, ri) => {
      const tr = h('tr');
      row.forEach((txt, ci) => tr.appendChild(cell('td', String(txt), {fontWeight: ci === 0 && o.first !== false ? S.fw.semi : S.fw.reg}, (n, c) => {
        n.style.color = c.text;
        n.style.backgroundColor = mark.includes(ri) ? c.accentSoft : 'transparent';
        n.style.borderBottom = ri < rows.length - 1 ? '1px solid ' + c.border : 'none';
      })));
      body.appendChild(tr);
    });
    table.appendChild(body);
    const wrap = h('div', {style: {overflowX: 'auto', border: '1px solid', borderRadius: S.r.md, margin: '0 0 ' + S.sp[5]}}, [table]);
    return AP2.theme.bind(wrap, (n, c) => { n.style.borderColor = c.border; n.style.backgroundColor = c.surface; });
  };
})();
;
// ui/procon.js
// Vorteile/Nachteile (Pro/Contra) als zwei Karten nebeneinander.
(function () {
  const {h, rich} = AP2;
  const S = AP2.S;
  const side = (label, items, tone, iconName) => {
    const head = h('div', {style: {display: 'flex', alignItems: 'center', gap: S.sp[2], fontWeight: S.fw.bold,
      fontSize: S.f.sm, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: S.sp[3]}}, [AP2.icon(iconName, 16), label]);
    AP2.tint(head, tone);
    const card = h('div', {style: {flex: '1 1 280px', padding: '16px 20px', borderRadius: S.r.md, border: '1px solid',
      borderTopWidth: '3px'}}, [head]);
    AP2.theme.bind(card, (n, c) => { n.style.backgroundColor = c.surface; n.style.borderColor = c.border; n.style.borderTopColor = c[tone]; });
    items.forEach((txt) => card.appendChild(AP2.tint(h('div', {style: {fontSize: S.f.sm, lineHeight: S.lh.body, padding: '3px 0'}}, rich(txt)), 'text')));
    return card;
  };
  AP2.blocks.procon = (title, pros, cons, labels) => {
    const names = labels || ['Vorteile', 'Nachteile'];
    const row = h('div', {style: {display: 'flex', flexWrap: 'wrap', gap: S.sp[4]}}, [side(names[0], pros, 'ok', 'plus'), side(names[1], cons, 'bad', 'minus')]);
    const head = AP2.tint(h('div', {text: title, style: {fontWeight: S.fw.semi, fontSize: S.f.lg, marginBottom: S.sp[3]}}), 'text');
    return h('div', {style: {margin: '0 0 ' + S.sp[5]}}, [head, row]);
  };
})();
;
// ui/highlight.js
// Kleiner Syntax-Highlighter: liefert Token [art, text] für Code-Blöcke.
(function () {
  const WORDS = {
    sql: 'select from where and or not in like between join inner left right full outer on group by having order asc desc insert into values update set delete create table primary key foreign references null is as distinct count sum avg min max limit alter drop add constraint unique default exists union all check varchar int integer date decimal char boolean text case when then else end view index',
    python: 'def class return if elif else for while in not and or import from as try except finally raise with pass break continue None True False lambda self print range len yield is',
    java: 'public private protected class interface extends implements static final void int double float long boolean char byte short String new return if else for while do switch case break continue try catch finally throw throws this super null true false abstract import package instanceof enum var List ArrayList Map HashMap Override System',
    csharp: 'using namespace public private protected internal class interface struct static readonly void int double float long bool char string var new return if else for foreach in while do switch case break continue try catch finally throw this base null true false abstract virtual override get set async await List Console enum record is as',
    js: 'function const let var return if else for while do switch case break continue try catch finally throw new this null true false class extends async await import export typeof of in',
    pseudo: 'wenn sonst dann ende solange für bis wiederhole funktion prozedur gib zurück ausgabe eingabe if else while for do then end return function falls rückgabe mod und oder nicht start wahr falsch mit schrittweite',
    c: 'int long float double char void unsigned const static struct return if else for while do switch case break continue sizeof include define NULL',
    cpp: 'int long float double char void bool unsigned const static struct class public private protected return if else for while do switch case break continue new delete this true false include define nullptr auto std',
    php: 'function return if else elseif foreach for while echo new class public private protected static null true false array isset as',
    json: 'true false null',
  };
  const COMMENT = {
    sql: /--[^\n]*/, python: /#[^\n]*/, pseudo: /\/\/[^\n]*|#[^\n]*/, java: /\/\/[^\n]*|\/\*[\s\S]*?\*\//,
    c: /\/\/[^\n]*|\/\*[\s\S]*?\*\//, cpp: /\/\/[^\n]*|\/\*[\s\S]*?\*\//, php: /\/\/[^\n]*|#[^\n]*|\/\*[\s\S]*?\*\//,
    csharp: /\/\/[^\n]*|\/\*[\s\S]*?\*\//, js: /\/\/[^\n]*|\/\*[\s\S]*?\*\//, html: /<!--[\s\S]*?-->/, css: /\/\*[\s\S]*?\*\//,
  };
  const SPECIAL = {html: /<\/?[A-Za-z][\w-]*|\/?>/, css: /[\w-]+(?=\s*:)/};
  const STR = /"(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*'/;
  const NUM = /\b\d+(?:\.\d+)?\b/;
  const WORD = /[A-Za-zÄÖÜäöüß_][\wÄÖÜäöüß]*/;
  const NEVER = /(?!)/;
  const cache = {};
  const make = (lang) => {
    const parts = [COMMENT[lang] || NEVER, STR, NUM, SPECIAL[lang] || NEVER, WORD];
    const set = new Set((WORDS[lang] || '').split(' '));
    const ci = lang === 'sql' || lang === 'pseudo';
    return {re: new RegExp(parts.map((part) => '(' + part.source + ')').join('|'), 'g'), set, ci};
  };
  AP2.highlight = (lang, src) => {
    const lex = cache[lang] || (cache[lang] = make(lang));
    const out = [];
    let last = 0;
    lex.re.lastIndex = 0;
    let m = lex.re.exec(src);
    while (m) {
      if (m.index > last) out.push(['plain', src.slice(last, m.index)]);
      let kind = 'plain';
      if (m[1]) kind = 'com';
      else if (m[2]) kind = 'str';
      else if (m[3]) kind = 'num';
      else if (m[4]) kind = 'kw';
      else if (lex.set.has(lex.ci ? m[5].toLowerCase() : m[5])) kind = 'kw';
      out.push([kind, m[0]]);
      last = m.index + m[0].length;
      m = lex.re.exec(src);
    }
    if (last < src.length) out.push(['plain', src.slice(last)]);
    return out;
  };
})();
;
// ui/code.js
// Code-Block mit Sprachlabel, Syntaxfarben und Kopieren-Knopf.
(function () {
  const {h} = AP2;
  const S = AP2.S;
  const COLORS = {kw: 'accent', str: 'ok', num: 'text', com: 'text3', plain: 'text'};
  const LABEL = {sql: 'SQL', python: 'Python', java: 'Java', csharp: 'C#', js: 'JavaScript', html: 'HTML', css: 'CSS', pseudo: 'Pseudocode', text: 'Text', c: 'C', cpp: 'C++', php: 'PHP', json: 'JSON'};
  const copyBtn = (src) => {
    const btn = AP2.btn({text: 'Kopieren', kind: 'ghost', small: true, fn: () => {
      try { navigator.clipboard.writeText(src); btn.firstChild.textContent = 'Kopiert'; } catch (err) { btn.firstChild.textContent = 'Nicht möglich'; }
      setTimeout(() => { btn.firstChild.textContent = 'Kopieren'; }, 1400);
    }});
    return btn;
  };
  AP2.blocks.code = (lang, source) => {
    const src = source.replace(/^\n+|\s+$/g, '');
    const spans = AP2.highlight(lang, src).map(([kind, txt]) => [kind, h('span', {text: txt})]);
    const pre = h('pre', {style: {margin: 0, padding: '4px 20px 18px', overflowX: 'auto', fontFamily: S.font.mono,
      fontSize: S.f.sm, lineHeight: S.lh.code, tabSize: 4}}, spans.map((pair) => pair[1]));
    const tag = AP2.tint(h('div', {text: LABEL[lang] || lang, style: {fontSize: S.f.xs, fontWeight: S.fw.bold, letterSpacing: '0.08em',
      textTransform: 'uppercase'}}), 'text3');
    const head = h('div', {style: {display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 12px 0 20px'}}, [tag, copyBtn(src)]);
    const box = h('div', {style: {border: '1px solid', borderRadius: S.r.md, margin: '0 0 ' + S.sp[5], overflow: 'hidden'}}, [head, pre]);
    return AP2.theme.bind(box, (node, c) => {
      st(node, c);
      spans.forEach(([kind, el]) => { el.style.color = c[COLORS[kind]]; el.style.fontWeight = kind === 'kw' ? S.fw.semi : S.fw.reg; el.style.fontStyle = kind === 'com' ? 'italic' : 'normal'; });
    });
    function st(node, c) { node.style.backgroundColor = c.surface2; node.style.borderColor = c.border; }
  };
})();
;
// ui/codetabs.js
// Mehrere Sprachen für dasselbe Beispiel: Reiter oberhalb eines Code-Blocks.
(function () {
  const {h} = AP2;
  const S = AP2.S;
  const NAMES = {sql: 'SQL', python: 'Python', java: 'Java', csharp: 'C#', js: 'JavaScript', html: 'HTML', css: 'CSS', pseudo: 'Pseudocode', text: 'Text', c: 'C', cpp: 'C++', php: 'PHP', json: 'JSON'};
  AP2.blocks.codes = (list) => {
    let cur = 0;
    const holder = h('div');
    const bar = h('div', {style: {display: 'flex', flexWrap: 'wrap', gap: S.sp[2], marginBottom: S.sp[2]}});
    const tabs = list.map((item, idx) => {
      const el = h('div', {text: NAMES[item[0]] || item[0], style: {padding: '6px 14px', borderRadius: S.r.pill, border: '1px solid', fontSize: S.f.sm, fontWeight: S.fw.med}});
      return AP2.press(el, {role: 'tab', fn: () => { cur = idx; show(); }, hover: (c) => ({borderColor: c.accent}),
        base: (c) => (cur === idx ? {backgroundColor: c.accent, color: c.onAccent, borderColor: c.accent} : {backgroundColor: c.surface, color: c.text2, borderColor: c.border})});
    });
    tabs.forEach((tab) => bar.appendChild(tab));
    function show() {
      AP2.dispose(holder);
      holder.appendChild(AP2.blocks.code(list[cur][0], list[cur][1]));
      tabs.forEach((tab) => tab.repaint());
    }
    show();
    const root = h('div', {attrs: {'data-seek': ''}}, [bar, holder]);
    // Die Suche wechselt auf den Reiter, dessen Code die Fundstelle enthält.
    root.ap2Seek = (needle) => {
      const idx = list.findIndex((item) => AP2.index.sk(item[1]).includes(needle));
      if (idx < 0) return false;
      cur = idx;
      show();
      return true;
    };
    return root;
  };
})();
;
