// content/infra/raid-1.js
(function () {
  // Baut ein Diagramm aus Plattenspalten mit Blöcken. cells[d][r] = [Text, Stil]
  const raid = (cells, title) => {
    const nodes = [];
    cells.forEach((col, d) => {
      const x = 56 + d * 84;
      nodes.push({id: 'd' + d, k: 'group', x, y: 24 + (col.length * 36 + 30) / 2, w: 74, h: col.length * 36 + 30, t: 'Platte ' + (d + 1), s: 'soft'});
      col.forEach((cell, r) => nodes.push({id: 'c' + d + '_' + r, k: 'box', x, y: 62 + r * 36, w: 52, h: 28, t: cell[0], s: cell[1] || 'plain', fs: 12}));
    });
    return {w: cells.length * 84 + 28, h: cells[0].length * 36 + 50, nodes, edges: [], cap: title};
  };
  const P = 'accent';
  const Q = 'bad';
  const r0 = raid([[['A1'], ['A3'], ['A5']], [['A2'], ['A4'], ['A6']]], 'RAID 0');
  const r1 = raid([[['A1'], ['A2'], ['A3']], [['A1', 'ok'], ['A2', 'ok'], ['A3', 'ok']]], 'RAID 1');
  const r5 = raid([[['A1'], ['B1'], ['C1'], ['Dp', P]], [['A2'], ['B2'], ['Cp', P], ['D1']], [['A3'], ['Bp', P], ['C2'], ['D2']], [['Ap', P], ['B3'], ['C3'], ['D3']]], 'RAID 5 (p = Parität)');
  const r6 = raid([[['A1'], ['B1'], ['Cp', P], ['Dq', Q]], [['A2'], ['Bp', P], ['Cq', Q], ['D1']], [['Ap', P], ['Bq', Q], ['C1'], ['D2']], [['Aq', Q], ['B2'], ['C2'], ['Dp', P]]], 'RAID 6 (p, q = zwei Paritäten)');
  const r10 = raid([[['A1'], ['A3']], [['A1', 'ok'], ['A3', 'ok']], [['A2'], ['A4']], [['A2', 'ok'], ['A4', 'ok']]], 'RAID 10 (1+0)');
  AP2.page('infra-raid', {
    b: 'infra', g: 'Storage und Verfügbarkeit', t: 'RAID-Level (0 bis 6, 10) und Kapazitätsberechnung',
    d: '**RAID** (Redundant Array of Independent Disks) fasst **mehrere Festplatten** zu einem **logischen Laufwerk** zusammen, für mehr **Leistung** (Striping), mehr **Ausfallsicherheit** (Spiegelung, Parität) oder beides. **RAID ersetzt kein Backup!**',
    m: '**RAID 0 = Tempo ohne Sicherheit (Striping). RAID 1 = Spiegel. RAID 5 = ein Platten darf ausfallen (Parität), Nutzkapazität (n-1). RAID 6 = zwei dürfen ausfallen, (n-2). RAID 10 = Spiegel plus Striping, n/2.** Eselsbrücke: Null = Null Sicherheit.',
    cheat: [
      ['Level und Mindestplatten', ['**RAID 0:** 2 Platten (Striping)', '**RAID 1:** 2 Platten (Spiegelung)', '**RAID 5:** 3 Platten (Parität)', '**RAID 6:** 4 Platten (doppelte Parität)', '**RAID 10:** 4 Platten (Spiegel + Striping)']],
      ['Nutzkapazität (n Platten, je c)', ['RAID 0: **n mal c**', 'RAID 1: **c** (bei 2 Platten)', 'RAID 5: **(n - 1) mal c**', 'RAID 6: **(n - 2) mal c**', 'RAID 10: **(n / 2) mal c**']],
      ['Ausfalltoleranz', ['RAID 0: **keine**', 'RAID 1: **1** Platte (von 2)', 'RAID 5: **1** Platte', 'RAID 6: **2** Platten', 'RAID 10: je Spiegelpaar **1** Platte']],
      ['Wichtig', ['**RAID ist kein Backup** (Löschen, Virus, Brand)', '**Hot Spare:** Reserveplatte für automatischen Rebuild', '**Rebuild** dauert lange, in dieser Zeit erhöhtes Risiko']],
    ],
    blocks: [
      ['h', 'Wozu RAID?'],
      ['p', 'Eine einzelne Festplatte kann **jederzeit ausfallen**. Der Ausfall würde den Server stoppen und Daten kosten. RAID verteilt die Daten auf mehrere Platten, sodass der Server **weiterläuft**, wenn eine Platte ausfällt (je nach Level). Man unterscheidet drei Grundprinzipien:'],
      ['kv', [
        ['Striping', 'Daten werden in **Streifen (Stripes)** abwechselnd auf mehrere Platten verteilt. Ergibt **mehr Geschwindigkeit** (parallele Zugriffe), aber **keine Redundanz**.'],
        ['Mirroring (Spiegelung)', 'Jedes Datum wird **doppelt** auf zwei Platten gespeichert. Ergibt **Ausfallsicherheit**, kostet aber die **halbe Kapazität**.'],
        ['Parität', 'Aus den Datenblöcken wird per **XOR** ein **Paritätsblock** berechnet. Fällt eine Platte aus, kann ihr Inhalt aus den **übrigen Daten und der Parität** wiederhergestellt werden. Spart Platz gegenüber Spiegelung.'],
      ]],
      ['h', 'Die RAID-Level im Detail'],
      ['h3', 'RAID 0: Striping'],
      ['p', 'Daten werden verteilt. **Schnell**, volle Kapazität, aber **ein Ausfall zerstört alle Daten**. Nur für unwichtige, schnelle Daten (Videoschnitt-Zwischenspeicher).'],
      ['diagram', r0],
      ['h3', 'RAID 1: Mirroring'],
      ['p', 'Jede Platte hat eine **exakte Kopie**. Fällt eine aus, läuft die andere weiter. Lesen ist schnell, Schreiben so schnell wie eine Platte. Nutzkapazität: **50 Prozent**.'],
      ['diagram', r1],
    ],
  });
  AP2.raidDiagrams = {r5, r6, r10};
})();
;
// content/infra/raid-2.js
AP2.add('infra-raid', [
  ['h3', 'RAID 5: Striping mit verteilter Parität'],
  ['p', 'Die Daten werden verteilt und zusätzlich wird ein **Paritätsblock** berechnet. Die Parität liegt **abwechselnd auf allen Platten**. **Eine** Platte darf ausfallen. Mindestens **3 Platten**. Nutzkapazität: **(n - 1)** Platten. Lesen schnell, **Schreiben langsamer** (Parität muss berechnet werden, "Write Penalty").'],
  ['diagram', AP2.raidDiagrams.r5],
  ['h3', 'RAID 6: doppelte Parität'],
  ['p', 'Wie RAID 5, aber mit **zwei unabhängigen Paritätsblöcken (P und Q)**. **Zwei** Platten dürfen gleichzeitig ausfallen. Mindestens **4 Platten**. Nutzkapazität: **(n - 2)** Platten. Sinnvoll bei **großen Platten**, weil der Rebuild lange dauert und in dieser Zeit eine zweite Platte ausfallen könnte.'],
  ['diagram', AP2.raidDiagrams.r6],
  ['h3', 'RAID 10 (1+0): Spiegel plus Striping'],
  ['p', 'Zuerst werden Plattenpaare **gespiegelt** (RAID 1), dann werden die Paare **zusammengefasst** (RAID 0). Mindestens **4 Platten**, Nutzkapazität **50 Prozent**. **Schnell** beim Lesen und Schreiben und **sehr sicher**: Pro Spiegelpaar darf eine Platte ausfallen. Fällt aber **beide Platten eines Paares** aus, sind die Daten verloren. Gut für Datenbanken.'],
  ['diagram', AP2.raidDiagrams.r10],
  ['table', ['Level', 'Min. Platten', 'Nutzkapazität', 'Ausfalltoleranz', 'Lesen', 'Schreiben', 'Typischer Einsatz'], [
    ['**RAID 0**', '2', 'n mal c (100 %)', 'keine', 'sehr gut', 'sehr gut', 'Temporäre Daten, Tempo'],
    ['**RAID 1**', '2', 'c (50 %)', '1 Platte', 'gut', 'normal', 'Betriebssystem, kleine Server'],
    ['**RAID 5**', '3', '(n-1) mal c', '1 Platte', 'gut', 'mittel (Parität)', 'Dateiserver, allgemeine Server'],
    ['**RAID 6**', '4', '(n-2) mal c', '2 Platten', 'gut', 'langsamer', 'Große Arrays, Archive'],
    ['**RAID 10**', '4', 'n/2 mal c (50 %)', '1 je Spiegelpaar', 'sehr gut', 'sehr gut', 'Datenbanken, hohe Last'],
  ]],
  ['note', 'Es gibt weitere Kombinationen: **RAID 01** (zuerst Striping, dann Spiegel), **RAID 50** und **RAID 60** (RAID 5/6 Gruppen, die gestriped werden) sowie **JBOD** ("Just a Bunch Of Disks": einfach zusammengefasst, ohne Redundanz). **RAID 2, 3 und 4** sind veraltet.'],
  ['h', 'Kapazität berechnen: Schema'],
  ['steps', ['**Level, Anzahl n und Größe c** der Platten ablesen.', 'Formel des Levels anwenden (siehe Tabelle).', 'Einheit angeben (TB, GB). Bei Dezimal-Angaben des Herstellers rechnen (1 TB = 1000 GB), das Betriebssystem zeigt oft weniger an.']],
  ['ex', ['**6 Platten mit je 4 TB:**', 'RAID 0: 6 mal 4 = **24 TB**', 'RAID 5: (6 - 1) mal 4 = **20 TB**', 'RAID 6: (6 - 2) mal 4 = **16 TB**', 'RAID 10: (6 / 2) mal 4 = **12 TB**', 'RAID 1: nur 2 Platten möglich, 4 TB (bei 6 Platten: Mehrfachspiegel).']],
  ['tool', 'raid'],
  ['h', 'Hot Spare, Rebuild und Grenzen'],
  ['list', ['**Hot Spare:** Eine zusätzliche Platte, die im Normalbetrieb ungenutzt ist und beim Ausfall automatisch einspringt (**Rebuild** beginnt sofort).', '**Rebuild:** Wiederherstellung der Daten auf der Ersatzplatte. Dauert bei großen Platten **Stunden bis Tage**, in dieser Zeit sinkt Leistung und Redundanz.', '**Hot Swap:** Platte kann im laufenden Betrieb getauscht werden.', '**Hardware- und Software-RAID:** Ein **RAID-Controller** (mit Cache und Batterie) übernimmt die Arbeit, oder das Betriebssystem (Windows Storage Spaces, Linux mdadm, ZFS).']],
  ['warn', ['**RAID ist kein Backup!** RAID schützt nur vor dem **Ausfall einer Platte**. Es schützt **nicht** vor versehentlichem Löschen, Viren und Ransomware, Softwarefehlern, Brand, Diebstahl oder einem Controller-Defekt. Auch ein gespiegeltes Löschen ist ein Löschen.']],
  ['h', 'Aufgaben im Prüfungsstil'],
  ['qa', 'Ein Server soll mit 5 Festplatten zu je 2 TB als RAID 5 betrieben werden. Berechnen Sie die Nutzkapazität und nennen Sie die Ausfalltoleranz.', ['Nutzkapazität = (n - 1) mal c = (5 - 1) mal 2 TB = **8 TB**.', 'Ausfalltoleranz: **eine** Platte darf ausfallen (die Kapazität einer Platte, 2 TB, wird für die Parität verwendet).'], 4],
  ['qa', 'Vergleichen Sie RAID 5 und RAID 10 für einen Datenbankserver. Wofür entscheiden Sie sich?', 'RAID 10 ist beim **Schreiben deutlich schneller**, weil keine Parität berechnet werden muss, und beim Rebuild nur eine Platte kopiert wird. Nachteil: Nutzkapazität nur 50 Prozent. RAID 5 bietet mehr Kapazität, schreibt aber langsamer (Write Penalty). Für **schreibintensive Datenbanken** ist **RAID 10** die bessere Wahl.', 5],
  ['qa', 'Warum ersetzt ein RAID-System keine Datensicherung?', 'RAID schützt nur vor dem Ausfall von Festplatten. Datenverlust durch Bedienfehler, Schadsoftware (Ransomware), Softwarefehler, Controller-Defekt, Brand oder Diebstahl wird auf alle Platten repliziert bzw. betrifft das ganze System. Nur ein getrenntes Backup (Kopie an anderem Ort) ermöglicht die Wiederherstellung früherer Stände.', 4],
  ['qa', 'Wie viele Platten dürfen bei RAID 6 ausfallen und warum setzt man RAID 6 bei sehr großen Platten ein?', '**Zwei** Platten. Bei großen Platten dauert der Rebuild lange; in dieser Zeit könnte eine zweite Platte ausfallen (oder ein Lesefehler auftreten). RAID 6 verkraftet das, RAID 5 nicht.', 3],
  ['quiz', [
    {q: 'Welches RAID-Level bietet KEINE Ausfallsicherheit?', o: ['RAID 0', 'RAID 1', 'RAID 5', 'RAID 6'], a: 0, e: 'RAID 0 (Striping) hat keine Redundanz. Eine ausgefallene Platte zerstört alle Daten.'},
    {q: '4 Platten mit je 1 TB im RAID 5: Wie groß ist die Nutzkapazität?', o: ['3 TB', '4 TB', '2 TB', '1 TB'], a: 0, e: '(4 - 1) mal 1 TB = 3 TB.'},
    {q: 'Wie viele Platten braucht RAID 10 mindestens?', o: ['4', '2', '3', '6'], a: 0, e: 'Zwei Spiegelpaare, die gestriped werden: mindestens 4 Platten.'},
    {q: 'Wie viele Platten dürfen bei RAID 6 gleichzeitig ausfallen?', o: ['2', '1', '3', '0'], a: 0, e: 'RAID 6 hat doppelte Parität.'},
    {q: '8 Platten je 3 TB als RAID 10: Nutzkapazität?', o: ['12 TB', '24 TB', '21 TB', '18 TB'], a: 0, e: '(8 / 2) mal 3 TB = 12 TB.'},
    {q: 'Wofür dient ein Hot Spare?', o: ['Er springt bei Plattenausfall automatisch ein', 'Er beschleunigt das Lesen', 'Er ersetzt das Backup', 'Er kühlt den Server'], a: 0, e: 'Eine Reserveplatte startet nach dem Ausfall automatisch den Rebuild.'},
  ]],
]);
;
// content/infra/verfuegbarkeit-1.js
AP2.page('infra-verfuegbarkeit', {
  b: 'infra', g: 'Storage und Verfügbarkeit', t: 'Verfügbarkeit, SLA, MTBF und MTTR',
  d: '**Verfügbarkeit** ist der Anteil der Zeit, in dem ein System **funktionsfähig** ist: **V = MTBF / (MTBF + MTTR)**. **MTBF** (Mean Time Between Failures) ist die mittlere Zeit zwischen zwei Ausfällen, **MTTR** (Mean Time To Repair) die mittlere Reparaturzeit. Ein **SLA** (Service Level Agreement) legt die zugesagte Verfügbarkeit und Reaktionszeiten vertraglich fest.',
  m: '**V = MTBF / (MTBF + MTTR).** Hohe Verfügbarkeit: **selten ausfallen (hohe MTBF) und schnell reparieren (niedrige MTTR).** Neunen: 99 % = 3,65 Tage Ausfall pro Jahr, **99,9 % = 8,76 Stunden**, **99,99 % = 52,6 Minuten**, 99,999 % = 5,3 Minuten.',
  cheat: [
    ['Formeln', ['**V = MTBF / (MTBF + MTTR)**', 'Ausfallzeit = **(1 - V) mal Betrachtungszeit**', 'Jahr = 365 Tage = **8760 Stunden**', '**Reihe:** V = V1 mal V2', '**Parallel:** V = 1 - (1 - V1) mal (1 - V2)']],
    ['Ausfallzeit pro Jahr', ['99 %: **87,6 h** (3,65 Tage)', '99,9 %: **8,76 h**', '99,99 %: **52,6 min**', '99,999 %: **5,26 min**']],
    ['Begriffe', ['**SLA:** Vereinbarung zur Servicequalität', '**RTO / RPO:** Wiederanlauf- / Datenverlustzeit', '**SPOF:** Single Point of Failure', '**Redundanz:** doppelte Auslegung']],
    ['Maßnahmen', ['RAID, redundante Netzteile', 'Cluster, Load Balancer', 'Zweiter Standort (Georedundanz)', 'USV und Generator, Monitoring']],
  ],
  blocks: [
    ['h', 'Was bedeutet Verfügbarkeit?'],
    ['p', 'Wenn ein Online-Shop nicht erreichbar ist, entgehen dem Unternehmen Umsatz und Vertrauen. **Verfügbarkeit** (englisch: Availability, Teil der **CIA-Triade**) ist deshalb ein wichtiges Qualitätsmerkmal. Man drückt sie in **Prozent** aus. Die Zahl hinter der Kommastelle zählt: aus 99 % werden 99,9 % ("drei Neunen"), das bedeutet einen **Faktor 10** weniger Ausfallzeit.'],
    ['table', ['Verfügbarkeit', 'Name', 'Ausfallzeit pro Jahr', 'pro Monat (30 Tage)', 'pro Woche'], [
      ['99 %', 'zwei Neunen', '87,6 Stunden (3,65 Tage)', '7,2 Stunden', '1,68 Stunden'],
      ['99,5 %', '-', '43,8 Stunden', '3,6 Stunden', '50,4 Minuten'],
      ['**99,9 %**', 'drei Neunen', '**8,76 Stunden**', '43,2 Minuten', '10,1 Minuten'],
      ['**99,99 %**', 'vier Neunen', '**52,6 Minuten**', '4,3 Minuten', '1 Minute'],
      ['99,999 %', 'fünf Neunen', '5,26 Minuten', '26 Sekunden', '6 Sekunden'],
    ]],
    ['chart', {kind: 'bar', w: 720, h: 320, labels: ['99 %', '99,5 %', '99,9 %', '99,99 %', '99,999 %'], series: [{n: 'Ausfallzeit pro Jahr in Stunden', d: [87.6, 43.8, 8.76, 0.88, 0.09], k: 'accent'}], vals: true, yl: 'Stunden pro Jahr', cap: 'Jede zusätzliche Neun verringert die erlaubte Ausfallzeit auf ein Zehntel.'}],
    ['h', 'MTBF, MTTR und die Formel'],
    ['kv', [
      ['MTBF', 'Mean Time Between Failures: **Durchschnittliche Betriebszeit zwischen zwei Ausfällen** bei reparierbaren Systemen. Beispiel: Eine Festplatte hat 500.000 Stunden MTBF (statistischer Wert für viele Platten, nicht die Lebensdauer einer einzelnen).'],
      ['MTTR', 'Mean Time To Repair (oder Recovery): **Durchschnittliche Zeit zur Behebung** eines Ausfalls (Erkennen, Anreise, Austausch, Wiederherstellung).'],
      ['MTTF', 'Mean Time To Failure: Wie MTBF, aber für **nicht reparierbare** Teile (zum Beispiel Lebensdauer einer Glühbirne).'],
    ]],
    ['code', 'text', `Verfügbarkeit V = MTBF / (MTBF + MTTR)

Beispiel: MTBF = 1000 Stunden, MTTR = 2 Stunden
V = 1000 / (1000 + 2) = 1000 / 1002 = 0,998 = 99,8 %
Ausfallzeit pro Jahr = (1 - 0,998) mal 8760 h = ca. 17,5 Stunden`],
    ['tool', 'avail'],
  ],
});
;
